// GEN_RFF_RoofingFilter.c  (GENERATED by analysis/harness/generator.py from the spec; edit the spec, not this file)
//
// PURPOSE:  Batch harness RFF. Feeds synthetic inputs through RoofingFilter (11 variants:
//           P48S10, P30S10, P125S10, P48S20, NCA [control], NCB [control], NCU [control], NCO [control], NC1 [control], NC1s [control], NC2 [control]) and writes the RAW outputs. It does NOT judge anything.
//           Python (analysis/harness/checker.py) measures and writes PASS/FAIL.
// PREREG:   analysis/harness/specs/RFF_ArticleFidelity.toml (this file)
// INPUTS:   Synthetic only, from the bar counter n: flat | level+amp*sin(2*pi*n/T), T=5,10,20,40,100 | alt level+amp*(-1)^n | ramp level+slope*n
//           level=11/10 amp=1/100 slope=1/10000. (b, H1 run 1) Decimal literals are float32 in this Zorro
//           build and the PI macro is 3.14159, so every constant is built at run time from integers.
//           EUR/USD is used only as a bar clock; clock_close is exported for the checker's magnitude guard.
// OUTPUT:   Data/GEN_RFF_raw.csv  (3000 rows n=0..2999 + header; 98 columns; values printed with 15 decimals)
// CALLS:    88 filter calls per bar, variant-major, unconditional, fixed order (gotchas 3.1).
// FEEDING:  every x[n], n=0..2999, reaches the filters exactly once; INITRUN and EXITRUN feed and write nothing.
// NO LOOKBACK GUARD: LookBack = 0, warmup bars are exported too; the checker requires n = 0..2999 contiguous.
// SOURCES:  expected values and tolerances are in the spec, each with an (a)/(b)/(c) label.
//           Pattern copied from strategies/tests/H1_SuperSmoother2Pole_Harness.c (b: H1 run 2 PASS).
// Y[] index = variant*8 + input.

#include <default.c>
#include "../../indicators/ehlers/HighPassFilter.c"
#include "../../indicators/ehlers/SuperSmoother2Pole.c"
#include "../../indicators/ehlers/RoofingFilter.c"

#define RFF_RAW "Data/GEN_RFF_raw.csv"
#define RFF_MARK "Data/GEN_RFF_exit_marker.txt"
#define RFF_NBARS 3000

static int rff_n = 0;
static int rff_done = 0;
static int rff_hdr = 0;
static int rff_rows = 0;
static int rff_sgn = 1;	// alt input sign, flipped once per fed bar (reset at INITRUN)

// NC-A: realistic copying error in the SuperSmoother pole factor (D2 rule 4). [corrected_code] pipeline, SuperSmoother inline, except a1 + 1/1000 (= bump3 at SS = 10: 0.6412807 -> 0.6422807 with Zorro PI, 0.6412805 -> 0.6422805 with exact pi) BEFORE b1, c3 and c0 are derived, so the DC gain stays 1. HighPassFilter is called (verified).
var rff_nca(vars Price, int HPP, int SSP)
{
	var* nca_hp = series(HighPassFilter(Price, HPP), 3);
	var nca_a1 = exp(-sqrt(2.0) * PI / SSP);
	nca_a1 = nca_a1 + 1.0 / 1000;
	var nca_b1 = 2.0 * nca_a1 * cos(sqrt(2.0) * PI / SSP);
	var nca_c3 = -nca_a1 * nca_a1;
	var nca_c0 = (1.0 - nca_b1 + nca_a1 * nca_a1) / 2.0;
	var* nca_f = series(nca_hp[0], 3);
	nca_f[0] = nca_c0 * (nca_hp[0] + nca_hp[1])
	        + nca_b1 * nca_f[1]
	        + nca_c3 * nca_f[2];
	return nca_f[0];
}

// NC-B: realistic copying error in the SuperSmoother input weight. [corrected_code] pipeline except c0 + 1/1000 (= bump3: 0.1265972 -> 0.1275972 with Zorro PI, 0.1265974 -> 0.1275974 with exact pi) AFTER the coefficients; both input taps change, so the DC gain is not 1.
var rff_ncb(vars Price, int HPP, int SSP)
{
	var* ncb_hp = series(HighPassFilter(Price, HPP), 3);
	var ncb_a1 = exp(-sqrt(2.0) * PI / SSP);
	var ncb_b1 = 2.0 * ncb_a1 * cos(sqrt(2.0) * PI / SSP);
	var ncb_c3 = -ncb_a1 * ncb_a1;
	var ncb_c0 = (1.0 - ncb_b1 + ncb_a1 * ncb_a1) / 2.0;
	ncb_c0 = ncb_c0 + 1.0 / 1000;
	var* ncb_f = series(ncb_hp[0], 3);
	ncb_f[0] = ncb_c0 * (ncb_hp[0] + ncb_hp[1])
	        + ncb_b1 * ncb_f[1]
	        + ncb_c3 * ncb_f[2];
	return ncb_f[0];
}

// NC-U: form mix-up, the SuperSmoother input is not averaged: Filt = (1 - b1 + a1*a1)*hp[0] + c2*Filt[1] + c3*Filt[2] (full weight on hp[0], no hp[1] term). DC gain stays 1; the Nyquist gain no longer vanishes (the only control that moves the alt gain).
var rff_ncu(vars Price, int HPP, int SSP)
{
	var* ncu_hp = series(HighPassFilter(Price, HPP), 3);
	var ncu_a1 = exp(-sqrt(2.0) * PI / SSP);
	var ncu_b1 = 2.0 * ncu_a1 * cos(sqrt(2.0) * PI / SSP);
	var ncu_c3 = -ncu_a1 * ncu_a1;
	var ncu_c0 = (1.0 - ncu_b1 + ncu_a1 * ncu_a1) / 2.0;
	var* ncu_f = series(ncu_hp[0], 3);
	ncu_f[0] = (1.0 - ncu_b1 + ncu_a1 * ncu_a1) * ncu_hp[0]
	        + ncu_b1 * ncu_f[1]
	        + ncu_c3 * ncu_f[2];
	return ncu_f[0];
}

// NCO: the old pipeline. The OLD HighPassFilter body (= HPF spec variant NCH: literal 0.707, history seeded at the price level, series(Price[0], 3)) feeding SuperSmoother2Pole as the current RoofingFilter.c does. Locals renamed only. Gain / phase effects are small (T = 20 gain 2.1e-5 < tolerance); caught by start-up (the seed) and by IMP must_fail (corrected model).
var rff_nco(vars Price, int HPP, int SSP)
{
	var nco_alpha1 = (cos(0.707*2.0*PI / HPP) + sin(0.707*2.0*PI / HPP) - 1.0)
	       / cos(0.707*2.0*PI / HPP);
	var* nco_hraw = series(Price[0], 3);
	nco_hraw[0] = (1.0 - nco_alpha1/2.0) * (1.0 - nco_alpha1/2.0)
	        * (Price[0] - 2.0*Price[1] + Price[2])
	        + 2.0*(1.0 - nco_alpha1) * nco_hraw[1]
	        - (1.0 - nco_alpha1) * (1.0 - nco_alpha1) * nco_hraw[2];
	var* nco_hp = series(nco_hraw[0], 3);
	var nco_out = SuperSmoother2Pole(nco_hp, SSP);
	return nco_out;
}

// NC2: gross units bug (gotchas section 2, mixed-file mode). SuperSmoother cosine argument in degrees (sqrt(2)*180/SSP) with the exponent unchanged. Stable at SS = 10 (pole radius a1 = 0.64).
var rff_nc2(vars Price, int HPP, int SSP)
{
	var* nc2_hp = series(HighPassFilter(Price, HPP), 3);
	var nc2_a1 = exp(-sqrt(2.0) * PI / SSP);
	var nc2_b1 = 2.0 * nc2_a1 * cos(sqrt(2.0) * 180.0 / SSP);
	var nc2_c3 = -nc2_a1 * nc2_a1;
	var nc2_c0 = (1.0 - nc2_b1 + nc2_a1 * nc2_a1) / 2.0;
	var* nc2_f = series(nc2_hp[0], 3);
	nc2_f[0] = nc2_c0 * (nc2_hp[0] + nc2_hp[1])
	        + nc2_b1 * nc2_f[1]
	        + nc2_c3 * nc2_f[2];
	return nc2_f[0];
}

void run()
{
	// Settings must be assigned on every call, including INITRUN, or Zorro never sees them.
	BarPeriod = 1440;
	StartDate = 20080101;
	EndDate   = 20240101;
	LookBack  = 0;
	asset("EUR/USD");

	if(is(INITRUN)) {
		rff_n = 0; rff_done = 0; rff_hdr = 0; rff_rows = 0; rff_sgn = 1;	// declared initialisers
		file_delete(RFF_RAW);
		file_delete(RFF_MARK);
		return;
	}
	if(is(EXITRUN)) {
		printf("\nRFF EXIT: rows written = %d, done = %d  (expected 3000 and 1)", rff_rows, rff_done);
		// marker file: if it exists after the run, EXITRUN ran even if the printf was lost (gotchas 9d.4)
		file_append(RFF_MARK, strf("EXITRUN ran: rows=%d done=%d\n", rff_rows, rff_done), 0);
		return;
	}

	int n;
	var X[8];
	var Y[88];
	n = rff_n;

	// --- constants built at RUN TIME from integers (gotchas 9d.1, 9d.2) ---
	var lvl = 11;	lvl = lvl / 10;
	var amp = 1;	amp = amp / 100;
	var slp = 1;	slp = slp / 10000;
	var pi_x = 4;	pi_x = pi_x * atan(1);

	// --- inputs from the bar counter (radians); no decimal literal, no PI macro ---
	X[0] = lvl;
	X[1] = lvl + amp * sin(2 * pi_x * n / 5);
	X[2] = lvl + amp * sin(2 * pi_x * n / 10);
	X[3] = lvl + amp * sin(2 * pi_x * n / 20);
	X[4] = lvl + amp * sin(2 * pi_x * n / 40);
	X[5] = lvl + amp * sin(2 * pi_x * n / 100);
	X[6] = lvl + amp * rff_sgn;
	X[7] = lvl + slp * n;

	// --- input series: 8 unconditional calls, fixed order ---
	vars S0 = series(X[0], 3);
	vars S1 = series(X[1], 3);
	vars S2 = series(X[2], 3);
	vars S3 = series(X[3], 3);
	vars S4 = series(X[4], 3);
	vars S5 = series(X[5], 3);
	vars S6 = series(X[6], 3);
	vars S7 = series(X[7], 3);

	// --- 88 filter calls, variant-major, unconditional, fixed order ---
	Y[0] = RoofingFilter(S0, 48, 10);	// P48S10 flat
	Y[1] = RoofingFilter(S1, 48, 10);	// P48S10 s5
	Y[2] = RoofingFilter(S2, 48, 10);	// P48S10 s10
	Y[3] = RoofingFilter(S3, 48, 10);	// P48S10 s20
	Y[4] = RoofingFilter(S4, 48, 10);	// P48S10 s40
	Y[5] = RoofingFilter(S5, 48, 10);	// P48S10 s100
	Y[6] = RoofingFilter(S6, 48, 10);	// P48S10 alt
	Y[7] = RoofingFilter(S7, 48, 10);	// P48S10 ramp
	Y[8] = RoofingFilter(S0, 30, 10);	// P30S10 flat
	Y[9] = RoofingFilter(S1, 30, 10);	// P30S10 s5
	Y[10] = RoofingFilter(S2, 30, 10);	// P30S10 s10
	Y[11] = RoofingFilter(S3, 30, 10);	// P30S10 s20
	Y[12] = RoofingFilter(S4, 30, 10);	// P30S10 s40
	Y[13] = RoofingFilter(S5, 30, 10);	// P30S10 s100
	Y[14] = RoofingFilter(S6, 30, 10);	// P30S10 alt
	Y[15] = RoofingFilter(S7, 30, 10);	// P30S10 ramp
	Y[16] = RoofingFilter(S0, 125, 10);	// P125S10 flat
	Y[17] = RoofingFilter(S1, 125, 10);	// P125S10 s5
	Y[18] = RoofingFilter(S2, 125, 10);	// P125S10 s10
	Y[19] = RoofingFilter(S3, 125, 10);	// P125S10 s20
	Y[20] = RoofingFilter(S4, 125, 10);	// P125S10 s40
	Y[21] = RoofingFilter(S5, 125, 10);	// P125S10 s100
	Y[22] = RoofingFilter(S6, 125, 10);	// P125S10 alt
	Y[23] = RoofingFilter(S7, 125, 10);	// P125S10 ramp
	Y[24] = RoofingFilter(S0, 48, 20);	// P48S20 flat
	Y[25] = RoofingFilter(S1, 48, 20);	// P48S20 s5
	Y[26] = RoofingFilter(S2, 48, 20);	// P48S20 s10
	Y[27] = RoofingFilter(S3, 48, 20);	// P48S20 s20
	Y[28] = RoofingFilter(S4, 48, 20);	// P48S20 s40
	Y[29] = RoofingFilter(S5, 48, 20);	// P48S20 s100
	Y[30] = RoofingFilter(S6, 48, 20);	// P48S20 alt
	Y[31] = RoofingFilter(S7, 48, 20);	// P48S20 ramp
	Y[32] = rff_nca(S0, 48, 10);	// NCA flat
	Y[33] = rff_nca(S1, 48, 10);	// NCA s5
	Y[34] = rff_nca(S2, 48, 10);	// NCA s10
	Y[35] = rff_nca(S3, 48, 10);	// NCA s20
	Y[36] = rff_nca(S4, 48, 10);	// NCA s40
	Y[37] = rff_nca(S5, 48, 10);	// NCA s100
	Y[38] = rff_nca(S6, 48, 10);	// NCA alt
	Y[39] = rff_nca(S7, 48, 10);	// NCA ramp
	Y[40] = rff_ncb(S0, 48, 10);	// NCB flat
	Y[41] = rff_ncb(S1, 48, 10);	// NCB s5
	Y[42] = rff_ncb(S2, 48, 10);	// NCB s10
	Y[43] = rff_ncb(S3, 48, 10);	// NCB s20
	Y[44] = rff_ncb(S4, 48, 10);	// NCB s40
	Y[45] = rff_ncb(S5, 48, 10);	// NCB s100
	Y[46] = rff_ncb(S6, 48, 10);	// NCB alt
	Y[47] = rff_ncb(S7, 48, 10);	// NCB ramp
	Y[48] = rff_ncu(S0, 48, 10);	// NCU flat
	Y[49] = rff_ncu(S1, 48, 10);	// NCU s5
	Y[50] = rff_ncu(S2, 48, 10);	// NCU s10
	Y[51] = rff_ncu(S3, 48, 10);	// NCU s20
	Y[52] = rff_ncu(S4, 48, 10);	// NCU s40
	Y[53] = rff_ncu(S5, 48, 10);	// NCU s100
	Y[54] = rff_ncu(S6, 48, 10);	// NCU alt
	Y[55] = rff_ncu(S7, 48, 10);	// NCU ramp
	Y[56] = rff_nco(S0, 48, 10);	// NCO flat
	Y[57] = rff_nco(S1, 48, 10);	// NCO s5
	Y[58] = rff_nco(S2, 48, 10);	// NCO s10
	Y[59] = rff_nco(S3, 48, 10);	// NCO s20
	Y[60] = rff_nco(S4, 48, 10);	// NCO s40
	Y[61] = rff_nco(S5, 48, 10);	// NCO s100
	Y[62] = rff_nco(S6, 48, 10);	// NCO alt
	Y[63] = rff_nco(S7, 48, 10);	// NCO ramp
	Y[64] = RoofingFilter(S0, 49, 10);	// NC1 flat
	Y[65] = RoofingFilter(S1, 49, 10);	// NC1 s5
	Y[66] = RoofingFilter(S2, 49, 10);	// NC1 s10
	Y[67] = RoofingFilter(S3, 49, 10);	// NC1 s20
	Y[68] = RoofingFilter(S4, 49, 10);	// NC1 s40
	Y[69] = RoofingFilter(S5, 49, 10);	// NC1 s100
	Y[70] = RoofingFilter(S6, 49, 10);	// NC1 alt
	Y[71] = RoofingFilter(S7, 49, 10);	// NC1 ramp
	Y[72] = RoofingFilter(S0, 48, 11);	// NC1s flat
	Y[73] = RoofingFilter(S1, 48, 11);	// NC1s s5
	Y[74] = RoofingFilter(S2, 48, 11);	// NC1s s10
	Y[75] = RoofingFilter(S3, 48, 11);	// NC1s s20
	Y[76] = RoofingFilter(S4, 48, 11);	// NC1s s40
	Y[77] = RoofingFilter(S5, 48, 11);	// NC1s s100
	Y[78] = RoofingFilter(S6, 48, 11);	// NC1s alt
	Y[79] = RoofingFilter(S7, 48, 11);	// NC1s ramp
	Y[80] = rff_nc2(S0, 48, 10);	// NC2 flat
	Y[81] = rff_nc2(S1, 48, 10);	// NC2 s5
	Y[82] = rff_nc2(S2, 48, 10);	// NC2 s10
	Y[83] = rff_nc2(S3, 48, 10);	// NC2 s20
	Y[84] = rff_nc2(S4, 48, 10);	// NC2 s40
	Y[85] = rff_nc2(S5, 48, 10);	// NC2 s100
	Y[86] = rff_nc2(S6, 48, 10);	// NC2 alt
	Y[87] = rff_nc2(S7, 48, 10);	// NC2 ramp

	// --- write one row per fed bar ---
	if(!rff_done) {
		if(!rff_hdr) {
			file_append(RFF_RAW, "n,clock_close,x_flat,x_s5,x_s10,x_s20,x_s40,x_s100,x_alt,x_ramp", 0);
			file_append(RFF_RAW, ",y_P48S10_flat,y_P48S10_s5,y_P48S10_s10,y_P48S10_s20,y_P48S10_s40,y_P48S10_s100,y_P48S10_alt,y_P48S10_ramp", 0);
			file_append(RFF_RAW, ",y_P30S10_flat,y_P30S10_s5,y_P30S10_s10,y_P30S10_s20,y_P30S10_s40,y_P30S10_s100,y_P30S10_alt,y_P30S10_ramp", 0);
			file_append(RFF_RAW, ",y_P125S10_flat,y_P125S10_s5,y_P125S10_s10,y_P125S10_s20,y_P125S10_s40,y_P125S10_s100,y_P125S10_alt,y_P125S10_ramp", 0);
			file_append(RFF_RAW, ",y_P48S20_flat,y_P48S20_s5,y_P48S20_s10,y_P48S20_s20,y_P48S20_s40,y_P48S20_s100,y_P48S20_alt,y_P48S20_ramp", 0);
			file_append(RFF_RAW, ",y_NCA_flat,y_NCA_s5,y_NCA_s10,y_NCA_s20,y_NCA_s40,y_NCA_s100,y_NCA_alt,y_NCA_ramp", 0);
			file_append(RFF_RAW, ",y_NCB_flat,y_NCB_s5,y_NCB_s10,y_NCB_s20,y_NCB_s40,y_NCB_s100,y_NCB_alt,y_NCB_ramp", 0);
			file_append(RFF_RAW, ",y_NCU_flat,y_NCU_s5,y_NCU_s10,y_NCU_s20,y_NCU_s40,y_NCU_s100,y_NCU_alt,y_NCU_ramp", 0);
			file_append(RFF_RAW, ",y_NCO_flat,y_NCO_s5,y_NCO_s10,y_NCO_s20,y_NCO_s40,y_NCO_s100,y_NCO_alt,y_NCO_ramp", 0);
			file_append(RFF_RAW, ",y_NC1_flat,y_NC1_s5,y_NC1_s10,y_NC1_s20,y_NC1_s40,y_NC1_s100,y_NC1_alt,y_NC1_ramp", 0);
			file_append(RFF_RAW, ",y_NC1s_flat,y_NC1s_s5,y_NC1s_s10,y_NC1s_s20,y_NC1s_s40,y_NC1s_s100,y_NC1s_alt,y_NC1s_ramp", 0);
			file_append(RFF_RAW, ",y_NC2_flat,y_NC2_s5,y_NC2_s10,y_NC2_s20,y_NC2_s40,y_NC2_s100,y_NC2_alt,y_NC2_ramp", 0);
			file_append(RFF_RAW, "\n", 0);
			rff_hdr = 1;
		}
		file_append(RFF_RAW, strf("%d,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", n, priceClose(), X[0], X[1], X[2], X[3], X[4], X[5], X[6]), 0);
		file_append(RFF_RAW, strf(",%.15f", X[7]), 0);
		file_append(RFF_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[0],Y[1],Y[2],Y[3],Y[4],Y[5],Y[6],Y[7]), 0);
		file_append(RFF_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[8],Y[9],Y[10],Y[11],Y[12],Y[13],Y[14],Y[15]), 0);
		file_append(RFF_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[16],Y[17],Y[18],Y[19],Y[20],Y[21],Y[22],Y[23]), 0);
		file_append(RFF_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[24],Y[25],Y[26],Y[27],Y[28],Y[29],Y[30],Y[31]), 0);
		file_append(RFF_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[32],Y[33],Y[34],Y[35],Y[36],Y[37],Y[38],Y[39]), 0);
		file_append(RFF_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[40],Y[41],Y[42],Y[43],Y[44],Y[45],Y[46],Y[47]), 0);
		file_append(RFF_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[48],Y[49],Y[50],Y[51],Y[52],Y[53],Y[54],Y[55]), 0);
		file_append(RFF_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[56],Y[57],Y[58],Y[59],Y[60],Y[61],Y[62],Y[63]), 0);
		file_append(RFF_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[64],Y[65],Y[66],Y[67],Y[68],Y[69],Y[70],Y[71]), 0);
		file_append(RFF_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[72],Y[73],Y[74],Y[75],Y[76],Y[77],Y[78],Y[79]), 0);
		file_append(RFF_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[80],Y[81],Y[82],Y[83],Y[84],Y[85],Y[86],Y[87]), 0);
		file_append(RFF_RAW, "\n", 0);
		rff_rows += 1;
		if(n == RFF_NBARS - 1) {
			rff_done = 1;	// latch first; nothing is written after this row
			quit("RFF batch complete: 3000 rows written");
		} else {
			rff_n += 1;
			rff_sgn = -rff_sgn;
		}
	}
}
